    private void setText(TextView v,String s){if(v==null)return;if(!v.getText().toString().equals(s))v.setText(s);}
    private void remember(View v,String key,boolean first){v.setId(View.generateViewId());focusViews.put(key,v);if(first)v.setNextFocusLeftId(activeNav().getId());v.setOnFocusChangeListener((w,f)->{w.setBackground(design.surface(f,12));if(f){lastContent=key;w.post(images::visible);}});}
    private TextView activeNav(){return navigation.get("home".equals(tab)?0:"search".equals(tab)?1:"favorites".equals(tab)?2:"queue".equals(tab)?3:4);}
    private boolean restoreFocus(String key){View v=focusViews.get(key);return v!=null&&v.isShown()&&v.requestFocus();}
    private void focusContent(){if(!restoreFocus(lastContent)){if("home".equals(tab)&&heroPlay!=null){heroPlay.requestFocus();return;}for(View v:focusViews.values())if(v.isShown()&&v.isFocusable()){v.requestFocus();return;}sourceButton.requestFocus();}}
    private boolean tabActive(int i){return i==0&&"home".equals(tab)||"favorites".equals(tab)&&(i==2&&"artists".equals(favoriteKind)||i==3&&"bands".equals(favoriteKind)||i==4&&"songs".equals(favoriteKind));}
    private TextView transport(){return "home".equals(tab)&&heroPlay!=null?heroPlay:play;}
    private void select(String page){if(query!=null)queryText=query.getText().toString();if(!"settings".equals(tab))returnTab=tab;tab=page;render();focusContent();}
