    private void render(){
        if(closed)return;String focused=lastContent;heroArt=null;heroSeek=null;heroTitle=null;heroArtist=null;heroSource=null;heroPlay=null;heroFavorite=null;heroElapsed=null;heroTotal=null;lyricPreview=null;heroArtKey="";lyricPreviewKey="";content.removeAllViews();focusViews.clear();images.clear();artKey="";query=null;status=null;
        setText(sourceButton,"soundcloud".equals(sourceName)?"SoundCloud ▾":"YouTube ▾");sourceButton.setVisibility("settings".equals(tab)?View.GONE:View.VISIBLE);
        for(int i=0;i<navigation.size();i++){TextView b=navigation.get(i);if(b==activeNav()||b.hasFocus())b.setBackground(design.surface(b.hasFocus(),12));else b.setBackgroundColor(Color.TRANSPARENT);}
        bar.setVisibility("home".equals(tab)?View.GONE:View.VISIBLE);
        for(int i=0;i<tabs.size();i++)tabs.get(i).setBackground(design.glass(tabActive(i),10,tabActive(i)));
        if("home".equals(tab)){home();}
        else if("search".equals(tab)){searchPage();}
        else if("favorites".equals(tab)){favorites();}
        else if("queue".equals(tab)){listPage(LauncherinPlayerService.tracks(this),true);}
        else{settings();}
        refresh();content.post(images::visible);
        if(!focused.isEmpty()&&focusViews.containsKey(focused))restoreFocus(focused);
    }
