    private void browseArtist(LauncherinMusicLibrary.Artist a){currentArtist=a;sourceName=a.source;library.source(sourceName);artistQuery=a.name;queryText=a.name;results.clear();tab="search";render();search();}
    private void artistActions(LauncherinMusicLibrary.Artist a){show(new AlertDialog.Builder(this).setTitle(a.name).setItems(new String[]{"Ouvir músicas deste artista","Editar nome, categoria e fonte","Remover dos favoritos"},(d,n)->{if(n==0){browseArtist(a);}else if(n==1)editArtist(a);else{library.removeArtist(a);if(currentArtist!=null&&currentArtist.key().equals(a.key()))currentArtist=null;render();focusContent();}}).setNegativeButton("Voltar",null).create());}
    private void editArtist(LauncherinMusicLibrary.Artist original){
        LauncherinTrack t=track();EditText name=new EditText(this);name.setSingleLine(true);name.setText(original!=null?original.name:t==null?"":t.artist.replaceFirst("(?i)\\s*-\\s*topic$",""));name.setHint("Nome do artista ou banda");name.setFilters(new InputFilter[]{new InputFilter.LengthFilter(120)});
        LinearLayout fields=column();fields.setPadding(dp(20),0,dp(20),0);fields.addView(name);TextView provider=button("Fonte: "+(original==null?sourceLabel():labelSource(original.source)),null,()->{});final String[] chosen={original==null?sourceName:original.source};provider.setOnClickListener(v->{chosen[0]="soundcloud".equals(chosen[0])?"youtube":"soundcloud";provider.setText("Fonte: "+labelSource(chosen[0]));});fields.addView(provider,new LinearLayout.LayoutParams(-1,dp(42)));final String[] kind={original==null?("bands".equals(favoriteKind)?"band":"artist"):original.kind};TextView category=button("Categoria: "+("band".equals(kind[0])?"Banda":"Artista"),null,()->{});category.setOnClickListener(v->{kind[0]="band".equals(kind[0])?"artist":"band";category.setText("Categoria: "+("band".equals(kind[0])?"Banda":"Artista"));});fields.addView(category,new LinearLayout.LayoutParams(-1,dp(42)));
        AlertDialog dialog=new AlertDialog.Builder(this).setTitle(original==null?"Artista ou banda favorita":"Editar artista").setView(fields).setPositiveButton("Salvar",null).setNegativeButton("Cancelar",null).create();
        dialog.setOnShowListener(d->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String value=name.getText().toString().trim();if(value.isEmpty()){name.setError("Informe o nome.");return;}String art=original!=null?original.art:t!=null&&value.equals(t.artist)?t.artistArt:"";try{LauncherinMusicLibrary.Artist a=new LauncherinMusicLibrary.Artist(value,chosen[0],art,kind[0]);if(original!=null)library.removeArtist(original);library.saveArtist(a);if(currentArtist!=null&&original!=null&&currentArtist.key().equals(original.key())){currentArtist=a;artistQuery=a.name;}dialog.dismiss();render();focusContent();}catch(IllegalArgumentException e){name.setError(e.getMessage());}}));show(dialog);
    }
    private void musicStrip(LinearLayout parent,List<LauncherinTrack> list){HorizontalScrollView s=new HorizontalScrollView(this);s.setHorizontalScrollBarEnabled(false);s.setClipToPadding(false);s.setOnScrollChangeListener((v,x,y,ox,oy)->images.visible());LinearLayout row=line();s.addView(row);parent.addView(s,new LinearLayout.LayoutParams(-1,dp(151)));for(int i=0;i<Math.min(16,list.size());i++){LinearLayout tile=musicCard(list,i,false);tile.setNextFocusLeftId(i==0?activeNav().getId():View.NO_ID);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(158),dp(146));p.rightMargin=dp(10);row.addView(tile,p);}TextView add=button("+\nAdicionar música",null,()->{artistQuery="";select("search");});add.setGravity(Gravity.CENTER);remember(add,"add-song",list.isEmpty());row.addView(add,new LinearLayout.LayoutParams(dp(142),dp(142)));}
    private LinearLayout musicCard(List<LauncherinTrack> list,int at,boolean queue){LauncherinTrack t=list.get(at);LinearLayout tile=column();tile.setPadding(dp(4),dp(4),dp(4),dp(5));ImageView image=new LauncherinMusicDesign.Image(this,false);image.setScaleType(ImageView.ScaleType.CENTER_CROP);image.setBackground(design.surface(false,9));image.setClipToOutline(true);tile.addView(image,new LinearLayout.LayoutParams(-1,0,1));TextView name=label(t.title,13,LauncherinMusicDesign.TEXT);name.setSingleLine(true);name.setEllipsize(TextUtils.TruncateAt.END);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(22));p.topMargin=dp(5);tile.addView(name,p);TextView artist=label(t.artist,11,LauncherinMusicDesign.MUTED);artist.setSingleLine(true);artist.setEllipsize(TextUtils.TruncateAt.END);tile.addView(artist);tile.setFocusable(true);tile.setClickable(true);tile.setContentDescription(t.title+", "+t.artist+", abrir ações da música");tile.setOnClickListener(v->musicActions(list,at,queue));tile.setOnLongClickListener(v->{musicActions(list,at,queue);return true;});remember(tile,"track:"+t.url,at%3==0);tile.setNextFocusDownId(play.getId());images.bind(image,t.art,320,240,design.placeholder(t.title,false));return tile;}
