    private void musicActions(List<LauncherinTrack> list,int at,boolean queue){LauncherinTrack t=list.get(at);String[] options=queue?new String[]{"Tocar a partir desta música","Adicionar novamente à fila",library.favorite(t)?"Remover música dos favoritos":"Favoritar música","Favoritar artista ou banda","Remover da fila"}:new String[]{"Tocar agora","Adicionar à fila",library.favorite(t)?"Remover música dos favoritos":"Favoritar música","Favoritar artista ou banda"};show(new AlertDialog.Builder(this).setTitle(t.title).setItems(options,(d,n)->{if(n==0){LauncherinPlayerService.play(this,new ArrayList<>(list),at);refresh();}else if(n==1){LauncherinPlayerService.enqueue(this,t);toast("Adicionada à fila");}else if(n==2){library.toggle(t);if("home".equals(tab)||"favorites".equals(tab))render();}else if(n==3){editArtist(new LauncherinMusicLibrary.Artist(t.artist.isEmpty()?"Artista":t.artist,"SoundCloud".equals(t.source)?"soundcloud":"youtube",t.artistArt));}else{if(t.url.equals(LauncherinPlayerService.snapshot(this).optString("url"))){toast("Escolha outra faixa antes de remover a atual.");return;}LauncherinPlayerService.remove(this,at);render();}}).setNegativeButton("Voltar",null).create());}

    private void searchPage(){LinearLayout col=column();content.addView(col,new FrameLayout.LayoutParams(-1,-1));LinearLayout line=line();query=new EditText(this);query.setId(View.generateViewId());query.setTextColor(LauncherinMusicDesign.TEXT);query.setTextSize(16);query.setHintTextColor(LauncherinMusicDesign.MUTED);query.setHint("Música, artista ou banda");query.setSingleLine(true);query.setPadding(dp(12),0,dp(12),0);query.setBackground(design.surface(false,12));query.setFilters(new InputFilter[]{new InputFilter.LengthFilter(160)});query.setImeOptions(EditorInfo.IME_ACTION_SEARCH);query.setText(queryText);line.addView(query,new LinearLayout.LayoutParams(0,dp(42),1));focusViews.put("search-input",query);query.setNextFocusLeftId(activeNav().getId());query.setOnFocusChangeListener((v,f)->{if(f)lastContent="search-input";});TextView find=button("Buscar","search",this::search);remember(find,"search-submit",false);LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(dp(118),dp(42));fp.leftMargin=dp(9);line.addView(find,fp);col.addView(line);if(currentArtist!=null){TextView manage=button("Artista favorito · opções","heart",()->artistActions(currentArtist));remember(manage,"artist-options",true);LinearLayout.LayoutParams mp=new LinearLayout.LayoutParams(-1,dp(34));mp.topMargin=dp(6);col.addView(manage,mp);}query.setNextFocusRightId(find.getId());find.setNextFocusLeftId(query.getId());query.setOnEditorActionListener((v,action,event)->{if(action==EditorInfo.IME_ACTION_SEARCH||event!=null&&event.getAction()==KeyEvent.ACTION_DOWN){search();return true;}return false;});
        status=label(busy?"Buscando músicas…":results.isEmpty()?"Digite e selecione Buscar.":"Resultados · "+sourceLabel(),12,LauncherinMusicDesign.MUTED);status.setPadding(0,dp(9),0,dp(9));col.addView(status);FrameLayout holder=new FrameLayout(this);col.addView(holder,new LinearLayout.LayoutParams(-1,0,1));ScrollView s=new ScrollView(this);s.setOnScrollChangeListener((v,x,y,ox,oy)->images.visible());LinearLayout songs=column();s.addView(songs);holder.addView(s,new FrameLayout.LayoutParams(-1,-1));if(!results.isEmpty())musicGrid(songs,results,false);
    }
    private void search(){if(query!=null)queryText=query.getText().toString().trim();if(queryText.isEmpty()){if(query!=null)query.requestFocus();return;}if(queryText.length()>160){toast("Use até 160 caracteres.");return;}if(!"search".equals(tab)){tab="search";render();}final int request=++searchGeneration;final String text=queryText;final boolean sc="soundcloud".equals(sourceName);busy=true;if(status!=null)status.setText("Buscando músicas…");if(searchJob!=null)searchJob.cancel(true);searchWorker.getQueue().clear();if(query!=null)getSystemService(InputMethodManager.class).hideSoftInputFromWindow(query.getWindowToken(),0);
        searchJob=searchWorker.submit(()->{try{List<LauncherinTrack> found=searchSource.search(text,sc);main.post(()->{if(closed||!active||request!=searchGeneration)return;busy=false;results=found;lastInteraction=SystemClock.elapsedRealtime();if("search".equals(tab)){lastContent="";render();if(status!=null)status.setText(found.isEmpty()?"Nenhuma música encontrada. Tente outra busca.":"Resultados · "+sourceLabel());if(!found.isEmpty())restoreFocus("track:"+found.get(0).url);}});}catch(Exception e){main.post(()->{if(!closed&&active&&request==searchGeneration){busy=false;if(status!=null)status.setText(LauncherinMusicSource.error(e));}});}});
    }
    private String sourceLabel(){return labelSource(sourceName);}
    private String labelSource(String s){return "soundcloud".equals(s)?"SoundCloud":"YouTube";}
    private void chooseSource(){show(new AlertDialog.Builder(this).setTitle("Fonte das músicas").setSingleChoiceItems(new String[]{"YouTube","SoundCloud"},"soundcloud".equals(sourceName)?1:0,(d,n)->{sourceName=n==1?"soundcloud":"youtube";library.source(sourceName);results.clear();++searchGeneration;if(searchJob!=null)searchJob.cancel(true);busy=false;d.dismiss();render();if("search".equals(tab)&&!queryText.isEmpty())search();}).setNegativeButton("Cancelar",null).create());}
    private void empty(LinearLayout col,String message,String action,Runnable click){TextView text=label(message,17,LauncherinMusicDesign.MUTED);text.setPadding(dp(8),dp(24),dp(8),dp(18));col.addView(text);TextView b=button(action,"add",click);remember(b,"empty-action",true);col.addView(b,new LinearLayout.LayoutParams(dp(210),dp(44)));}

    private void settings(){
        LinearLayout col=column();scroll(col);section(col,"Protetor durante o áudio");
        String[] ids={"cover","photos","dark","google"},titles={"Capa flutuante","Fotos em sequência","Modo escuro","Google Fotos"},notes={"Capa e informações mudam de posição.","Fotos enviadas ao Porta-retratos; informações em movimento.","Fundo preto e informações discretas em movimento.","Usa o álbum e o temporizador do modo ambiente da TV."};
        GridLayout modes=new GridLayout(this);modes.setColumnCount(2);col.addView(modes,new LinearLayout.LayoutParams(-1,-2));for(int i=0;i<ids.length;i++){String mode=ids[i];LinearLayout row=column();row.setPadding(dp(13),dp(8),dp(13),dp(8));row.setFocusable(true);row.setClickable(true);TextView name=label((mode.equals(library.saverMode())?"●  ":"○  ")+titles[i],16,LauncherinMusicDesign.TEXT);TextView note=label(notes[i],12,LauncherinMusicDesign.MUTED);note.setMaxLines(2);note.setEllipsize(TextUtils.TruncateAt.END);row.addView(name);row.addView(note);row.setOnClickListener(v->{library.saverMode(mode);lastContent="saver-mode:"+mode;render();});remember(row,"saver-mode:"+mode,i%2==0);row.setBackground(design.surface(mode.equals(library.saverMode()),12));GridLayout.LayoutParams p=new GridLayout.LayoutParams(GridLayout.spec(i/2),GridLayout.spec(i%2));p.width=Math.max(dp(120),((content.getWidth()>0?content.getWidth():getResources().getDisplayMetrics().widthPixels-dp(208))-dp(16))/2);p.height=dp(82);p.rightMargin=dp(8);p.bottomMargin=dp(8);modes.addView(row,p);}
        boolean google="google".equals(library.saverMode());TextView delay=button(google?"Tempo: definido no modo ambiente da TV":"Iniciar na tela de música: "+delayLabel(library.saverSeconds()),null,()->{if(google)googleInfo();else chooseDelay();});remember(delay,"saver-time",true);col.addView(delay,new LinearLayout.LayoutParams(-1,dp(43)));addGap(col,8);
        TextView preview=button(google?"Configurar álbum do Google Fotos":"Visualizar protetor",google?"settings":"saver",()->{if(google)openGoogleSettings();else startSaver(false);});remember(preview,"saver-preview",true);col.addView(preview,new LinearLayout.LayoutParams(-1,dp(43)));addGap(col,12);
        TextView info=label("Os modos próprios atuam nesta tela. Ao voltar à Home, vale o protetor configurado na TV. A música continua e a regra de desligamento é preservada.",12,LauncherinMusicDesign.MUTED);col.addView(info);addGap(col,18);
        TextView external=button("Usar controles de aplicativos externos",null,()->{LauncherinPlayerService.external(this);finish();});remember(external,"external",true);col.addView(external,new LinearLayout.LayoutParams(-1,dp(43)));TextView about=button("Sobre e licenças",null,this::about);remember(about,"about",true);LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(-1,dp(43));ap.topMargin=dp(8);col.addView(about,ap);
    }
    private String delayLabel(int seconds){return seconds==0?"Somente manual":seconds<60?seconds+" segundos":seconds/60+" minuto"+(seconds==60?"":"s");}
    private void chooseDelay(){int[] values={30,60,120,300,0};String[] labels=new String[values.length];int selected=1;for(int i=0;i<values.length;i++){labels[i]=delayLabel(values[i]);if(values[i]==library.saverSeconds())selected=i;}show(new AlertDialog.Builder(this).setTitle("Inatividade na tela de música").setSingleChoiceItems(labels,selected,(d,n)->{library.saverSeconds(values[n]);d.dismiss();render();}).setNegativeButton("Cancelar",null).create());}
    private void googleInfo(){show(new AlertDialog.Builder(this).setTitle("Google Fotos no protetor de áudio").setMessage("A música continua no player da Launcherin enquanto a TV mostra o álbum selecionado no seu modo ambiente.\n\nNa TCL com Android 14, a entrada acontece pelo tempo de inatividade configurado na própria TV. Escolha Google Fotos e o álbum nas configurações abaixo. A Launcherin não recebe sua senha nem baixa seu álbum privado.").setPositiveButton("Abrir modo ambiente",(d,n)->openGoogleSettings()).setNegativeButton("Voltar",null).create());}
    private void openGoogleSettings(){try{startActivity(new Intent(android.provider.Settings.ACTION_DREAM_SETTINGS));}catch(RuntimeException e){toast("Abra Configurações → Sistema → Modo ambiente na TV.");}}
    private void startSaver(boolean automatic){if(saver!=null)return;if("google".equals(library.saverMode())){if(!automatic)googleInfo();return;}LauncherinTrack t=track();if(t==null){if(!automatic)toast("Escolha uma música para visualizar o protetor.");return;}closeLyrics();saver=new LauncherinAudioSaverView(this,library.saverMode(),images);shell.setVisibility(View.GONE);root.addView(saver,new FrameLayout.LayoutParams(-1,-1));saver.requestFocus();saver.update(t,SystemClock.elapsedRealtime());}
    private void stopSaver(){if(saver==null)return;saver.release();root.removeView(saver);saver=null;shell.setVisibility(View.VISIBLE);lastInteraction=SystemClock.elapsedRealtime();root.setKeepScreenOn(false);transport().requestFocus();images.visible();}
    private void openLyrics(){LauncherinTrack t=track();if(t==null){toast("Escolha uma música para ver a letra.");return;}stopSaver();lyricsVisible=true;overlay.removeAllViews();overlay.setBackground(design.backdrop());overlay.setVisibility(View.VISIBLE);LinearLayout pane=column();pane.setPadding(dp(42),dp(24),dp(42),dp(24));overlay.addView(pane,new FrameLayout.LayoutParams(-1,-1));LinearLayout header=line();TextView back=button("Biblioteca","back",this::closeLyrics);header.addView(back,new LinearLayout.LayoutParams(dp(155),dp(42)));TextView song=label(t.title+" · "+t.artist,18,LauncherinMusicDesign.TEXT);song.setSingleLine(true);song.setEllipsize(TextUtils.TruncateAt.END);song.setPadding(dp(20),0,0,0);header.addView(song,new LinearLayout.LayoutParams(0,-2,1));pane.addView(header);
        ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setFocusable(true);lyricsText=label("Buscando letra…",26,LauncherinMusicDesign.TEXT);lyricsText.setGravity(Gravity.CENTER);lyricsText.setPadding(dp(50),dp(35),dp(50),dp(35));scroll.addView(lyricsText);pane.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));back.requestFocus();loadLyrics(t);
    }
    private void loadLyrics(LauncherinTrack t){if(t.url.equals(lyricsKey)&&lyrics!=null){lyricsLine=-2;renderLyrics(LauncherinPlayerService.snapshot(this).optLong("position"));return;}lyricsKey=t.url;lyrics=null;lyricsLine=-2;int request=++lyricsGeneration;if(lyricJob!=null)lyricJob.cancel(true);lyricJob=lyricWorker.submit(()->{LauncherinLyrics.Result result=null;try{result=LauncherinLyrics.load(this,t);}catch(Exception ignored){}final LauncherinLyrics.Result ready=result;main.post(()->{if(closed||!active||request!=lyricsGeneration||!(lyricsVisible||"home".equals(tab)))return;lyrics=ready==null?new LauncherinLyrics.Result("","",false):ready;renderLyrics(LauncherinPlayerService.snapshot(this).optLong("position"));});});}
    private void renderLyrics(long position){if(lyrics==null)return;if(lyricPreview!=null){int at=lyrics.at(position);String key=lyricsKey+":"+at+":"+lyrics.instrumental+":"+lyrics.plain;if(!key.equals(lyricPreviewKey)){lyricPreviewKey=key;if(lyrics.lines.isEmpty())lyricPreview.setText(lyrics.instrumental?"Faixa instrumental":lyrics.plain.isEmpty()?"Letra não encontrada para esta gravação.":lyrics.plain);else{SpannableStringBuilder preview=new SpannableStringBuilder();for(int i=Math.max(0,at-1);i<Math.min(lyrics.lines.size(),Math.max(3,at+2));i++){int start=preview.length();preview.append(lyrics.lines.get(i).text).append("\n");if(i==at){preview.setSpan(new ForegroundColorSpan(LauncherinMusicDesign.TEXT),start,preview.length(),Spannable.SPAN_EXCLUSIVE_EXCLUSIVE);preview.setSpan(new BackgroundColorSpan(0x805b35ba),start,preview.length(),Spannable.SPAN_EXCLUSIVE_EXCLUSIVE);preview.setSpan(new StyleSpan(Typeface.BOLD),start,preview.length(),Spannable.SPAN_EXCLUSIVE_EXCLUSIVE);}}lyricPreview.setText(preview);}}}if(!lyricsVisible||lyricsText==null)return;if(lyrics.lines.isEmpty()){String value=lyrics.instrumental?"Faixa instrumental":lyrics.plain.isEmpty()?"Letra não encontrada para esta gravação.":lyrics.plain;setText(lyricsText,value);return;}int at=lyrics.at(position);if(at==lyricsLine)return;lyricsLine=at;SpannableStringBuilder text=new SpannableStringBuilder();int first=Math.max(0,at-2),end=Math.min(lyrics.lines.size(),Math.max(5,at+3));for(int i=first;i<end;i++){int start=text.length();text.append(lyrics.lines.get(i).text).append("\n\n");text.setSpan(new ForegroundColorSpan(i==at?LauncherinMusicDesign.CYAN:0xff83938e),start,text.length(),Spannable.SPAN_EXCLUSIVE_EXCLUSIVE);if(i==at)text.setSpan(new StyleSpan(Typeface.BOLD),start,text.length(),Spannable.SPAN_EXCLUSIVE_EXCLUSIVE);}lyricsText.setText(text);}
    private void closeLyrics(){if(!lyricsVisible)return;lyricsVisible=false;overlay.setVisibility(View.GONE);overlay.removeAllViews();lastInteraction=SystemClock.elapsedRealtime();if(play!=null)transport().requestFocus();}
