    private void refresh(){
        if(closed||library==null)return;JSONObject snap=LauncherinPlayerService.snapshot(this);LauncherinTrack t=LauncherinTrack.read(snap);boolean playing=snap.optBoolean("playing"),buffering=snap.optBoolean("buffering");setText(clock,new java.text.SimpleDateFormat("HH:mm",Locale.getDefault()).format(new Date()));String control=buffering?"Cancelar carregamento":playing?"Pausar":"Reproduzir";if(!control.equals(play.getContentDescription())){play.setContentDescription(control);play.setForeground(new LauncherinMusicDesign.Icon(playing?"pause":"play",LauncherinMusicDesign.TEXT,dp(22)));}
        if(heroPlay!=null&&!control.equals(heroPlay.getContentDescription())){heroPlay.setContentDescription(control);heroPlay.setForeground(new LauncherinMusicDesign.Icon(playing?"pause":"play",LauncherinMusicDesign.TEXT,dp(27)));}
        setText(barTitle,t==null?"Escolha uma música":t.title);setText(barArtist,t==null?"Abra Buscar para começar":buffering?"Carregando áudio…":!snap.optString("error").isEmpty()?snap.optString("error"):t.artist);
        if(t!=null){String key=t.url+"|"+t.art;if(!key.equals(artKey)){artKey=key;images.bind(barArt,t.art,128,128,design.placeholder(t.title,false));}long pos=snap.optLong("position");seek.setProgress(t.duration>0?(int)Math.min(1000,Math.max(0,pos)*1000/t.duration):0);setText(elapsed,time(pos));setText(total,time(t.duration));if(!t.url.equals(lastTrack)){lastTrack=t.url;lyricsKey="";lyricPreviewKey="";if(lyricsVisible)openLyrics();}
            if(heroTitle!=null){setText(heroTitle,t.title);setText(heroArtist,t.artist);setText(heroSource,buffering?"Carregando áudio…":!snap.optString("error").isEmpty()?snap.optString("error"):t.source+" · Áudio");setText(heroFavorite,library.favorite(t)?"Favoritada":"Favoritar");setText(heroElapsed,time(pos));setText(heroTotal,time(t.duration));heroSeek.setProgress(t.duration>0?(int)Math.min(1000,Math.max(0,pos)*1000/t.duration):0);String picture=t.url+"|"+t.art;if(!picture.equals(heroArtKey)){heroArtKey=picture;images.bind(heroArt,t.art,480,480,design.placeholder(t.title,false));}}
            if(active&&(lyricsVisible||"home".equals(tab))){if(!t.url.equals(lyricsKey)){setText(lyricPreview,"Buscando letra…");loadLyrics(t);}renderLyrics(pos);}if(saver!=null)saver.update(t,SystemClock.elapsedRealtime());}
        else if(artKey.isEmpty()){barArt.setImageDrawable(design.placeholder("",false));if(heroArt!=null)heroArt.setImageDrawable(design.placeholder("",false));}
        boolean local=!"google".equals(library.saverMode())&&library.saverSeconds()>0;root.setKeepScreenOn(active&&playing&&(saver!=null||local&&!lyricsVisible&&!dialogOpen&&!busy&&!"settings".equals(tab)));
        if(active&&saver==null&&!lyricsVisible&&!"settings".equals(tab)&&LauncherinAudioSaverPolicy.start(library.saverMode(),library.saverSeconds(),playing,busy||dialogOpen||!hasWindowFocus(),lastInteraction,SystemClock.elapsedRealtime()))startSaver(true);
        images.visible();
    }
    private LauncherinTrack track(){return LauncherinTrack.read(LauncherinPlayerService.snapshot(this));}
    private void command(String action){if(LauncherinPlayerService.tracks(this).isEmpty()){artistQuery="";select("search");toast("Escolha uma música para começar.");return;}LauncherinPlayerService.command(this,action);}
    private void toast(String message){Toast.makeText(this,message,Toast.LENGTH_SHORT).show();}
    private void show(AlertDialog dialog){dialogOpen=true;dialog.setOnDismissListener(d->{dialogOpen=false;lastInteraction=SystemClock.elapsedRealtime();});dialog.show();}
    static String time(long ms){long seconds=Math.max(0,ms)/1000;return seconds/60+":"+String.format(Locale.ROOT,"%02d",seconds%60);}
    @Override public void onUserInteraction(){super.onUserInteraction();lastInteraction=SystemClock.elapsedRealtime();}
    @Override public boolean dispatchKeyEvent(KeyEvent event){
        int key=event.getKeyCode();if(dismissKey==key){if(event.getAction()==KeyEvent.ACTION_UP)dismissKey=-1;return true;}
        if(saver!=null&&event.getAction()==KeyEvent.ACTION_DOWN&&(key==KeyEvent.KEYCODE_BACK||key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER||key==KeyEvent.KEYCODE_DPAD_UP||key==KeyEvent.KEYCODE_DPAD_DOWN||key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT||key==KeyEvent.KEYCODE_MENU)){dismissKey=key;stopSaver();return true;}
        if(key==KeyEvent.KEYCODE_MEDIA_PLAY_PAUSE||key==KeyEvent.KEYCODE_MEDIA_NEXT||key==KeyEvent.KEYCODE_MEDIA_PREVIOUS){if(event.getAction()==KeyEvent.ACTION_DOWN&&event.getRepeatCount()==0)command(key==KeyEvent.KEYCODE_MEDIA_NEXT?"next":key==KeyEvent.KEYCODE_MEDIA_PREVIOUS?"previous":"toggle");return true;}return super.dispatchKeyEvent(event);
    }
    @Override public void onBackPressed(){if(saver!=null)stopSaver();else if(lyricsVisible)closeLyrics();else if(!"home".equals(tab)){artistQuery="";select("home");activeNav().requestFocus();}else super.onBackPressed();}
    @Override public void onWindowFocusChanged(boolean focus){super.onWindowFocusChanged(focus);if(focus){lastInteraction=SystemClock.elapsedRealtime();if(root!=null&&root.findFocus()==null)activeNav().requestFocus();}}
    @android.annotation.SuppressLint("UnspecifiedRegisterReceiverFlag")
    @Override protected void onStart(){super.onStart();active=true;lastInteraction=SystemClock.elapsedRealtime();if(Build.VERSION.SDK_INT>=33)registerReceiver(changed,new IntentFilter(LauncherinPlayerService.CHANGED),Context.RECEIVER_NOT_EXPORTED);else registerReceiver(changed,new IntentFilter(LauncherinPlayerService.CHANGED));images.resume();main.post(tick);}
    @Override protected void onStop(){active=false;root.setKeepScreenOn(false);main.removeCallbacks(tick);++searchGeneration;++lyricsGeneration;if(searchJob!=null)searchJob.cancel(true);searchWorker.getQueue().clear();if(lyricJob!=null)lyricJob.cancel(true);busy=false;lyricsKey="";unregisterReceiver(changed);images.pause();super.onStop();}
    @Override protected void onDestroy(){closed=true;main.removeCallbacksAndMessages(null);images.close();searchWorker.shutdownNow();lyricWorker.shutdownNow();super.onDestroy();}
